import * as T from './vendor/three.module.min.js';
const cube=new T.BoxGeometry(1,1,1),rock=new T.IcosahedronGeometry(1,0),cylinder=new T.CylinderGeometry(1,1,1,8),cone=new T.ConeGeometry(1,1,9),materials=new Map();
const mat=(color,glow=false,opacity=1)=>{const key=[color,glow,opacity].join(':');if(!materials.has(key))materials.set(key,glow?new T.MeshBasicMaterial({color,transparent:opacity<1,opacity,depthWrite:opacity===1}):new T.MeshToonMaterial({color}));return materials.get(key);};
function part(g,x,y,z,w,h,d,c,glow=false,geo=cube,opacity=1){const o=new T.Mesh(geo,mat(c,glow,opacity));o.position.set(x,y,z);o.scale.set(w,h,d);o.castShadow=!glow;o.receiveShadow=true;g.add(o);return o;}
function random(seed){return()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};}
function rockBatch(g,count,seed,width,height){const r=random(seed),mesh=new T.InstancedMesh(rock,mat('#514646'),count),stamp=new T.Object3D();for(let i=0;i<count;i++){stamp.position.set(r()*width,-.25,r()*height);stamp.scale.set(.3+r()*1.8,.2+r()*.4,.4+r()*1.2);stamp.rotation.set(0,r()*6.28,0);stamp.updateMatrix();mesh.setMatrixAt(i,stamp.matrix);}g.add(mesh);}
export function buildPlanet(group,m,coverMeshes){const r=random(m.seed),floor=part(group,m.width*.05,-1,m.height*.05,m.width*.1+200,2,m.height*.1+200,'#67514d');coverMeshes.push(floor);rockBatch(group,900,m.seed,m.width*.1,m.height*.1);
 // Flat mineral seams and ash strata break up the basin without hidden collision.
 for(let i=0;i<140;i++){const x=r()*m.width*.1,z=r()*m.height*.1,patch=part(group,x,.015,z,5+r()*22,.025,4+r()*12,i%5===0?'#8c6755':'#74615b',false,cylinder);patch.rotation.y=r()*6.28;}
 for(let i=0;i<16;i++){const x=110+r()*650,z=70+r()*510;for(let j=0;j<5;j++){const seam=part(group,x+j*3,.055,z+Math.sin(j)*1.2,3.6,.04,.22,'#ea8851',true);seam.rotation.y=Math.cos(j)*.3;}}
 for(const o of m.obstacles){const x=(o.x+o.w/2)*.1,z=(o.y+o.h/2)*.1,h=o.height*.1;const body=part(group,x,h*.5,z,o.w*.1,h,o.h*.1,o.rock?'#73594f':'#33414a',false,o.rock?rock:cube);if(o.rock)body.scale.multiplyScalar(.5);coverMeshes.push(body);if(o.rock){part(group,x,h+.4,z,o.w*.068,2,o.h*.07,'#84665b',false,rock);}else{part(group,x,h*.7,z-o.h*.05-.02,o.w*.085,.22,.1,'#eea657',true);part(group,x,h+.2,z,o.w*.1+.3,.4,o.h*.1+.3,'#879298');}}
 for(const p of m.platforms){const x=(p.x+p.w/2)*.1,z=(p.y+p.h/2)*.1;coverMeshes.push(part(group,x,p.z*.1-.4,z,p.w*.1,.8,p.h*.1,'#405057'));for(const side of[-1,1]){part(group,x+side*(p.w*.05-1),p.z*.05,z,1.6,p.z*.1,1.6,'#2b343c');part(group,x,p.z*.1+.05,z+side*(p.h*.05-.2),p.w*.1,.12,.3,'#8cebc9',true);}}
 for(const r of m.ramps){const hw=r.w*.05,hd=r.h*.05,y=r.z*.1,g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute([-hw,y,-hd,hw,y,-hd,hw,0,hd,-hw,y,-hd,hw,0,hd,-hw,0,hd],3));g.computeVertexNormals();const mesh=new T.Mesh(g,new T.MeshToonMaterial({color:'#48565a',side:T.DoubleSide}));mesh.position.set((r.x+r.w/2)*.1,0,(r.y+r.h/2)*.1);mesh.userData.ownGeometry=mesh.userData.ownMaterial=true;group.add(mesh);coverMeshes.push(mesh);}
 // Distinct landing pad, industrial route, extraction pad and a distant volcanic horizon.
 for(const [p,c]of[[m.entry,'#ffc988'],[m.exit,'#9effc7']]){part(group,p.x*.1,.04,p.y*.1,42,.08,42,'#26333a');for(const side of[-1,1]){part(group,p.x*.1+side*19,.15,p.y*.1,.5,.12,39,c,true);part(group,p.x*.1,.15,p.y*.1+side*19,39,.12,.5,c,true);}part(group,p.x*.1,.16,p.y*.1,1,.1,15,c,true);part(group,p.x*.1,.16,p.y*.1,15,.1,1,c,true);}
 for(let i=1;i<m.route.length;i++){const a=m.route[i-1],b=m.route[i],d=Math.hypot(b.x-a.x,b.y-a.y);for(let f=0;f<1;f+=100/d){const x=(a.x+(b.x-a.x)*f)*.1,z=(a.y+(b.y-a.y)*f)*.1;part(group,x,.08,z,1.2,.1,1.2,'#a8c7a9',true);}}
 for(let i=0;i<46;i++){const angle=i/46*Math.PI*2,cx=m.width*.05+Math.cos(angle)*(m.width*.065),cz=m.height*.05+Math.sin(angle)*(m.height*.07),h=35+r()*70;part(group,cx,h*.35-5,cz,65+r()*60,h,60+r()*65,i%2?'#51454e':'#70534f',false,cone);}
 const rx=m.reactor.x*.1+50,rz=m.reactor.y*.1+55;part(group,rx,16,rz,17,32,17,'#29353c',false,cylinder);part(group,rx,17,rz,18,2,18,'#f4a56d',true,cylinder);part(group,rx,31,rz,20,2,20,'#6b7f88',false,cylinder);for(const side of[-1,1]){part(group,rx+side*16,12,rz,4,24,4,'#3d4b54');part(group,rx+side*16,25,rz,5,2,5,'#ff9560',true);}
 const dynamic=new T.Group();group.add(dynamic);group.userData.operationFX=dynamic;return{sky:0x655660};
}
export function planetSky(group,m){const shell=new T.Mesh(new T.SphereGeometry(850,24,16),new T.ShaderMaterial({side:T.BackSide,depthWrite:false,fog:false,vertexShader:'varying vec3 p;void main(){p=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'varying vec3 p;void main(){float y=normalize(p).y;vec3 c=mix(vec3(.52,.34,.27),vec3(.13,.16,.25),smoothstep(-.1,.8,y));gl_FragColor=vec4(c,1.);}' }));shell.userData.ownGeometry=shell.userData.ownMaterial=true;group.add(shell);const moon=part(group,-220,155,420,70,70,70,'#cbb5ae',true,rock);moon.material.fog=false;const sun=part(group,330,160,-470,18,18,18,'#ffe0a2',true,rock);sun.material.fog=false;}
export function makeMissionObjective(e){const g=new T.Group(),color=e.objectiveKind==='cache'?'#95efc1':e.objectiveKind==='coolant'?'#65d7e4':'#ff9c62';part(g,0,.4,0,6,.8,6,'#27343c');part(g,0,2.6,0,3.6,4,3.6,'#48565d');const core=part(g,0,3.2,0,4,1.8,4,color,true,cylinder);g.userData.core=core;for(const side of[-1,1])part(g,side*2.1,3,0,.6,5,.6,'#8a9b9c');if(e.objectiveKind==='battery'){part(g,0,5,0,6,2,5,'#3c464e');const barrel=part(g,0,6,-3,1.8,1.8,9,'#333d48');barrel.rotation.x=-.45;}const shield=part(g,0,3,0,5,4.5,5,'#8ccaff',true,rock,.16);g.userData.shield=shield;return g;}
export function updateMissionObjective(g,e,t){g.position.set(e.x*.1,(e.altitude||0)*.1,e.y*.1);g.userData.shield.visible=!!e.locked;g.userData.core.rotation.y=t*.8;}
function ship(g){const s=new T.Group();g.add(s);part(s,0,0,0,10,4,20,'#28363e');part(s,0,1,-8,7,3,7,'#68838d');part(s,0,1.4,-11.6,5,1,.1,'#85edcd',true);for(const side of[-1,1]){part(s,side*9,-.4,1,13,1.2,10,'#405661');part(s,side*12,-1,1,4,3,7,'#26323e');part(s,side*12,-3,1,2.2,5,2.2,'#91edff',true,cone,.55);}return s;}
export function updatePlanet(group,w,t){const g=group.userData.operationFX;if(!g)return;const o=w.operation;if(!g.userData.ship){g.userData.ship=ship(g);const c=new T.Group();g.add(c);part(c,0,2,0,12,4,18,'#34444a');part(c,0,5,-4,8,4,8,'#698386');part(c,0,5,-8.1,6,1.5,.1,'#acffc7',true);for(const side of[-1,1])for(let j=0;j<3;j++)part(c,side*7,1,-6+j*6,2.5,3,4,'#202c32');g.userData.crawler=c;g.userData.cells=Array.from({length:6},()=>{const p=new T.Group();g.add(p);part(p,0,1.5,0,1.4,3,1.4,'#abffd0',true,rock);return p;});g.userData.drops=Array.from({length:36},()=>{const p=part(g,0,0,0,.4,25,.4,'#ffb582',true);return p;});}
 if(!g.userData.heavyZone){const zone=new T.Group();g.add(zone);for(const side of[-1,1]){part(zone,side*17,.12,0,.45,.2,34,'#ffc49a',true);part(zone,0,.12,side*17,34,.2,.45,'#ffc49a',true);part(zone,side*17,8,side*17,.35,16,.35,'#ff9d70',true);}g.userData.heavyZone=zone;}
 const alert=o.heavyAlert,zone=g.userData.heavyZone;zone.visible=!!alert&&w.time<alert.landingAt;if(zone.visible){zone.position.set(alert.x*.1,0,alert.y*.1);zone.scale.setScalar(1+Math.sin(t*8)*.025);}
 const s=g.userData.ship;s.visible=w.time<12||o.phase===4;const pad=o.phase===4?w.mission.exit:w.mission.entry,remaining=o.phase===4?o.shipAt-w.time:6-w.time;s.position.set(pad.x*.1,remaining>0?Math.min(100,8+remaining*7):o.phase===4?8:8+(w.time-6)*13,pad.y*.1);s.rotation.y=.3;
 const c=g.userData.crawler;c.visible=o.phase>=2;c.position.set(o.crawler.x*.1,0,o.crawler.y*.1);const next=w.mission.route[Math.min(o.crawler.segment+1,w.mission.route.length-1)];c.rotation.y=-Math.atan2(next.y-o.crawler.y,next.x-o.crawler.x)-Math.PI/2;
 g.userData.cells.forEach((p,i)=>{const cell=o.cells[i],carrier=cell?.carrier&&w.players.find(p=>p.id===cell.carrier);p.visible=!!cell&&['loose','carried'].includes(cell.state);if(!p.visible)return;p.position.set((carrier?.x??cell.x)*.1,((carrier?.altitude??cell.z)+75)*.1,(carrier?.y??cell.y)*.1);p.rotation.y=t*2;});
 g.userData.drops.forEach((p,i)=>{const event=(w.spawn?.length?w.spawn:w.pendingDrops)?.[i];p.visible=!!event;if(event)p.position.set(event.zone.x*.1,13,event.zone.y*.1);});
}
